package com.mt.boostgamesuper.view.base;import android.content.BroadcastReceiver;import android.content.Context;import android.content.Intent;/** * Created by Thangmx. */public class ConnectivityChangeReceiver extends BroadcastReceiver {    private OnConnectivityChangedListener listener;    public ConnectivityChangeReceiver(OnConnectivityChangedListener listener) {        this.listener = listener;    }    @Override    public void onReceive(final Context context, final Intent intent) {        if (checkInternet(context))            listener.onConnectivityChanged(false);        else            listener.onConnectivityChanged(true);    }    boolean checkInternet(Context context) {        ServiceManager serviceManager = new ServiceManager(context);        if (serviceManager.isNetworkAvailable()) {            return true;        } else {            return false;        }    }    public interface OnConnectivityChangedListener {        void onConnectivityChanged(boolean isConnected);    }}